#define ALPN "papacc/1"
typedef enum MODE{VALID=0,TLS12,WRONG_TRUST,WRONG_NAME,WRONG_ALPN,STALL,RESET}MODE;
static int pair(SOCKET*c,SOCKET*s){SOCKET l=INVALID_SOCKET;struct sockaddr_in a;int z=sizeof(a);u_long nb=1;l=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);if(l==INVALID_SOCKET)return 0;memset(&a,0,sizeof(a));a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);if(bind(l,(struct sockaddr*)&a,sizeof(a))||listen(l,1)||getsockname(l,(struct sockaddr*)&a,&z))goto bad;*c=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);if(*c==INVALID_SOCKET||connect(*c,(struct sockaddr*)&a,sizeof(a)))goto bad;*s=accept(l,NULL,NULL);if(*s==INVALID_SOCKET)goto bad;closesocket(l);l=INVALID_SOCKET;if(ioctlsocket(*c,FIONBIO,&nb)||ioctlsocket(*s,FIONBIO,&nb))goto bad;return 1;bad:if(l!=INVALID_SOCKET)closesocket(l);if(*c!=INVALID_SOCKET){closesocket(*c);*c=INVALID_SOCKET;}if(*s!=INVALID_SOCKET){closesocket(*s);*s=INVALID_SOCKET;}return 0;}
static void server_config(PST_CONNECTION_CONFIG*c,pst_credentials*id,MODE m){static const PST_ALPN_PROTOCOL good={(const pst_u8*)ALPN,sizeof(ALPN)-1U},wrong={(const pst_u8*)"wrong/1",7U};memset(c,0,sizeof(*c));c->struct_size=sizeof(*c);c->api_version=PST_API_VERSION;c->role=PST_CONNECTION_ROLE_SERVER;c->provider_selection.struct_size=sizeof(c->provider_selection);c->provider_selection.api_version=PST_API_VERSION;c->provider_selection.mode=PST_BACKEND_SELECTION_EXACT;c->provider_selection.exact_provider_id="openssl";c->provider_selection.required_capabilities=(m==TLS12?PST_CAP_TLS_1_2:PST_CAP_TLS_1_3)|PST_CAP_ROLE_SERVER|PST_CAP_LOCAL_IDENTITY|PST_CAP_ALPN_SERVER|PST_CAP_NONBLOCKING|PST_CAP_BACKEND_WAIT|PST_CAP_GRACEFUL_SHUTDOWN;c->local_identity.struct_size=sizeof(c->local_identity);c->local_identity.api_version=PST_API_VERSION;c->local_identity.credentials=id;c->peer_authentication.struct_size=sizeof(c->peer_authentication);c->peer_authentication.api_version=PST_API_VERSION;c->peer_authentication.certificate_mode=PST_PEER_CERTIFICATE_DISABLED;c->tls.struct_size=sizeof(c->tls);c->tls.api_version=PST_API_VERSION;c->tls.minimum_version=m==TLS12?PST_TLS_VERSION_1_2:PST_TLS_VERSION_1_3;c->tls.maximum_version=c->tls.minimum_version;c->tls.resumption=PST_FEATURE_DISABLED;c->tls.early_data=PST_FEATURE_DISABLED;c->tls.require_graceful_shutdown=PST_FEATURE_REQUIRED;c->alpn.struct_size=sizeof(c->alpn);c->alpn.api_version=PST_API_VERSION;c->alpn.mode=PST_FEATURE_REQUIRED;c->alpn.protocols=m==WRONG_ALPN?&wrong:&good;c->alpn.protocol_count=1U;}
static int scenario(pst_runtime*r,PAPACC_TEST_SECURITY_FIXTURE*f,pst_trust*system,MODE m){PST_CONNECTION_CONFIG sc;PAPACC_OUTBOUND_TLS_POLICY p;PAPACC_OUTBOUND_TLS client=PAPACC_OUTBOUND_TLS_INITIALIZER;pst_connection*server=NULL;pst_transport*t=NULL;SOCKET cs=INVALID_SOCKET,ss=INVALID_SOCKET;pst_u32 accepted=0,op=PST_OPERATION_NEED_READ;PST_RESULT source=PST_RESULT_OK;PAPACC_BOOL done=PAPACC_FALSE,expired=PAPACC_FALSE;int i,ok=0;server_config(&sc,f->server.credentials,m);if(!pair(&cs,&ss))goto cleanup;if(m==RESET){struct linger x={1,0};setsockopt(ss,SOL_SOCKET,SO_LINGER,(const char*)&x,sizeof(x));closesocket(ss);ss=INVALID_SOCKET;}else if(m!=STALL){if(pst_connection_create(r,&sc,&server)!=PST_RESULT_OK||pst_win32_socket_transport_create(ss,&t)!=PST_RESULT_OK||pst_connection_attach(server,t,PST_OWNERSHIP_TRANSFERRED,&accepted)!=PST_RESULT_OK||!accepted)goto cleanup;ss=INVALID_SOCKET;t=NULL;}memset(&p,0,sizeof(p));p.runtime=r;p.trust=m==WRONG_TRUST?system:f->trust;p.provider_id="openssl";p.alpn=(const PAPACC_U8*)ALPN;p.alpn_size=sizeof(ALPN)-1U;p.alpn_required=PAPACC_TRUE;if(papacc_outbound_tls_init(&client,&p,m==WRONG_NAME?"wrong.example":"papacc-test-server",100U)!=PAPACC_RESULT_OK||papacc_outbound_tls_attach_socket(&client,cs)!=PAPACC_RESULT_OK)goto cleanup;cs=INVALID_SOCKET;if(m==STALL){if(papacc_outbound_tls_handshake_once(&client,&done)==PAPACC_RESULT_OK&&!done&&papacc_outbound_tls_check_deadline(&client,101U,&expired)==PAPACC_RESULT_OK&&expired)ok=1;goto cleanup;}for(i=0;i<10000&&!done;i++){PAPACC_RESULT cr=papacc_outbound_tls_handshake_once(&client,&done);PST_RESULT sr=server?pst_connection_handshake(server,&op,&source):PST_RESULT_OK;if(cr!=PAPACC_RESULT_OK||sr!=PST_RESULT_OK||op==PST_OPERATION_FAILED)break;}ok=m==VALID?done:!done;cleanup:papacc_outbound_tls_abort(&client);if(server)pst_connection_release(server);if(t)pst_transport_release(t);if(cs!=INVALID_SOCKET)closesocket(cs);if(ss!=INVALID_SOCKET)closesocket(ss);return ok;}
int main(void){WSADATA w;PST_RUNTIME_OPTIONS o;PST_TRUST_SOURCE ts;pst_runtime*r=NULL;pst_trust*system=NULL;PAPACC_TEST_SECURITY_FIXTURE f=PAPACC_TEST_SECURITY_FIXTURE_INITIALIZER;int result=0;CHECK(WSAStartup(MAKEWORD(2,2),&w)==0,1);CHECK(pst_win32_register_builtin_providers()==PST_RESULT_OK,2);memset(&o,0,sizeof(o));o.struct_size=sizeof(o);o.api_version=PST_API_VERSION;CHECK(pst_runtime_create(&o,&r)==PST_RESULT_OK,3);CHECK(papacc_test_security_fixture_init(&f),4);memset(&ts,0,sizeof(ts));ts.struct_size=sizeof(ts);ts.api_version=PST_API_VERSION;ts.kind=PST_TRUST_SOURCE_SYSTEM;CHECK(pst_trust_create(&ts,&system)==PST_RESULT_OK,5);CHECK(scenario(r,&f,system,VALID),10);CHECK(scenario(r,&f,system,TLS12),11);CHECK(scenario(r,&f,system,WRONG_TRUST),12);CHECK(scenario(r,&f,system,WRONG_NAME),13);CHECK(scenario(r,&f,system,WRONG_ALPN),14);CHECK(scenario(r,&f,system,STALL),15);CHECK(scenario(r,&f,system,RESET),16);cleanup:if(system)pst_trust_release(system);papacc_test_security_fixture_release(&f);if(r)pst_runtime_release(r);WSACleanup();return result;}
